package com.rulecraft.decisionops.workflow;

import com.rulecraft.decisionops.audit.AuditService;import com.rulecraft.decisionops.catalog.domain.DecisionServiceStatus;import com.rulecraft.decisionops.catalog.persistence.DecisionServiceRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import com.rulecraft.decisionops.versions.domain.*;import com.rulecraft.decisionops.versions.persistence.DecisionVersionRepository;import com.rulecraft.decisionops.workflow.domain.*;import com.rulecraft.decisionops.workflow.persistence.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Service
public class ApprovalWorkflowService {
    private final DecisionChangeRequestRepository requests;private final DecisionChangeEventRepository events;private final DecisionPromotionRepository promotions;private final DecisionVersionRepository versions;private final DecisionServiceRepository services;private final ProjectAccessPolicy access;private final AuditService audit;private final Clock clock;
    public ApprovalWorkflowService(DecisionChangeRequestRepository requests,DecisionChangeEventRepository events,DecisionPromotionRepository promotions,DecisionVersionRepository versions,DecisionServiceRepository services,ProjectAccessPolicy access,AuditService audit,Clock clock){this.requests=requests;this.events=events;this.promotions=promotions;this.versions=versions;this.services=services;this.access=access;this.audit=audit;this.clock=clock;}

    @Transactional(readOnly=true)public WorkflowView workflow(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){context(actor,projectId,serviceId);var latest=latest(actor,serviceId);var items=requests.findTop100ByTenantIdAndProjectIdAndServiceIdOrderByRequestNumberDesc(actor.tenantId(),projectId,serviceId).stream().map(request->view(actor,request,latest)).toList();var promotion=promotions.findByServiceIdAndTenantIdAndProjectId(serviceId,actor.tenantId(),projectId).map(value->promotion(actor,projectId,serviceId,value)).orElse(null);return new WorkflowView(items,promotion,access.roleFor(actor,projectId));}
    @Transactional(readOnly=true)public RequestDetail detail(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId){context(actor,projectId,serviceId);var request=require(actor,projectId,serviceId,requestId);var timeline=events.findByRequestIdOrderByCreatedAtAsc(requestId).stream().map(this::event).toList();return new RequestDetail(view(actor,request,latest(actor,serviceId)),timeline);}

    @Transactional public RequestView create(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,CreateCommand command){access.requireEdit(actor,projectId);service(actor,projectId,serviceId);if(command==null||command.clientRequestId()==null)bad("RC-WORKFLOW-REQUEST-ID","Provide a client request ID so retries remain idempotent.");var retry=requests.findByTenantIdAndServiceIdAndClientRequestId(actor.tenantId(),serviceId,command.clientRequestId());if(retry.isPresent())return view(actor,retry.get(),latest(actor,serviceId));var locked=services.lockForVersionCapture(serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);if(locked.getStatus()!=DecisionServiceStatus.ACTIVE)conflict("RC-WORKFLOW-SERVICE-ARCHIVED","Restore the decision service before opening a change request.");var candidate=version(actor,projectId,serviceId,command.decisionVersionId());requireLatestValid(actor,serviceId,candidate);var title=clean(command.title(),160,"RC-WORKFLOW-TITLE","Change request titles contain 1–160 characters.");var summary=optional(command.summary(),2000,"RC-WORKFLOW-SUMMARY","Change request summaries contain at most 2,000 characters.");if(requests.findByTenantIdAndServiceIdAndDecisionVersionId(actor.tenantId(),serviceId,candidate.getId()).isPresent())conflict("RC-WORKFLOW-VERSION-EXISTS","This decision version already has a change request.");if(requests.countByTenantIdAndServiceId(actor.tenantId(),serviceId)>=1000)bad("RC-WORKFLOW-LIMIT","A decision service can retain at most 1,000 change requests.");var number=requests.findFirstByTenantIdAndServiceIdOrderByRequestNumberDesc(actor.tenantId(),serviceId).map(value->value.getRequestNumber()+1).orElse(1);var now=Instant.now(clock);DecisionChangeRequest value;try{value=requests.saveAndFlush(new DecisionChangeRequest(actor.tenantId(),projectId,serviceId,candidate.getId(),command.clientRequestId(),number,title,summary,actor.userId(),actor.displayName(),now));}catch(DataIntegrityViolationException race){var duplicate=requests.findByTenantIdAndServiceIdAndClientRequestId(actor.tenantId(),serviceId,command.clientRequestId());if(duplicate.isPresent())return view(actor,duplicate.get(),latest(actor,serviceId));conflict("RC-WORKFLOW-CONCURRENT","Another change request was opened. Refresh before retrying.");return null;}events.save(new DecisionChangeEvent(actor.tenantId(),value.getId(),command.clientRequestId(),"CREATED",null,ChangeRequestState.DRAFT,summary,actor.userId(),actor.displayName(),now));record(actor,value,"CREATED");return view(actor,value,candidate);}

    @Transactional public RequestView submit(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId,TransitionCommand command){access.requireEdit(actor,projectId);return transition(actor,projectId,serviceId,requestId,command,"SUBMITTED",Set.of(ChangeRequestState.DRAFT),ChangeRequestState.SUBMITTED,false,true);}
    @Transactional public RequestView requestChanges(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId,TransitionCommand command){access.requireReview(actor,projectId);return transition(actor,projectId,serviceId,requestId,command,"CHANGES_REQUESTED",Set.of(ChangeRequestState.SUBMITTED),ChangeRequestState.CHANGES_REQUESTED,true,false);}
    @Transactional public RequestView approve(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId,TransitionCommand command){access.requireReview(actor,projectId);return transition(actor,projectId,serviceId,requestId,command,"APPROVED",Set.of(ChangeRequestState.SUBMITTED),ChangeRequestState.APPROVED,false,true);}
    @Transactional public RequestView reject(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId,TransitionCommand command){access.requireReview(actor,projectId);return transition(actor,projectId,serviceId,requestId,command,"REJECTED",Set.of(ChangeRequestState.SUBMITTED),ChangeRequestState.REJECTED,true,false);}
    @Transactional public RequestView promote(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId,TransitionCommand command){access.requirePromote(actor,projectId);var value=transition(actor,projectId,serviceId,requestId,command,"PROMOTED",Set.of(ChangeRequestState.APPROVED),ChangeRequestState.PROMOTED,false,true);var existing=promotions.findByServiceIdAndTenantIdAndProjectId(serviceId,actor.tenantId(),projectId);if(existing.isPresent()&&requestId.equals(existing.get().getRequestId()))return value;var now=Instant.now(clock);var promotion=existing.orElseGet(()->new DecisionPromotion(serviceId,actor.tenantId(),projectId));promotion.promote(requestId,value.decisionVersionId(),actor.userId(),actor.displayName(),now);promotions.save(promotion);return value;}

    private RequestView transition(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId,TransitionCommand command,String eventType,Set<ChangeRequestState> allowed,ChangeRequestState next,boolean noteRequired,boolean latestRequired){service(actor,projectId,serviceId);if(command==null||command.clientRequestId()==null)bad("RC-WORKFLOW-REQUEST-ID","Provide a client request ID so retries remain idempotent.");var locked=services.lockForVersionCapture(serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);if(locked.getStatus()!=DecisionServiceStatus.ACTIVE)conflict("RC-WORKFLOW-SERVICE-ARCHIVED","Restore the decision service before continuing the workflow.");var request=requests.lockScoped(requestId,actor.tenantId(),projectId,serviceId).orElseThrow(this::notFound);var retried=events.findByRequestIdAndClientRequestId(requestId,command.clientRequestId());if(retried.isPresent()){if(!retried.get().getEventType().equals(eventType))conflict("RC-WORKFLOW-IDEMPOTENCY-CONFLICT","That request ID was already used for another workflow action.");return view(actor,request,latest(actor,serviceId));}if(command.expectedVersion()==null||command.expectedVersion()!=request.getVersion())conflict("RC-WORKFLOW-STALE","The change request changed. Refresh before retrying.");if(!allowed.contains(request.getState()))conflict("RC-WORKFLOW-TRANSITION","The requested transition is not allowed from "+request.getState()+".");var note=optional(command.note(),2000,"RC-WORKFLOW-NOTE","Workflow notes contain at most 2,000 characters.");if(noteRequired&&note==null)bad("RC-WORKFLOW-NOTE-REQUIRED","Explain the requested changes or rejection.");var candidate=version(actor,projectId,serviceId,request.getDecisionVersionId());if(latestRequired)requireLatestValid(actor,serviceId,candidate);var previous=request.getState();var now=Instant.now(clock);request.transition(next,now);requests.saveAndFlush(request);events.save(new DecisionChangeEvent(actor.tenantId(),requestId,command.clientRequestId(),eventType,previous,next,note,actor.userId(),actor.displayName(),now));record(actor,request,eventType);return view(actor,request,latest(actor,serviceId));}

    private void requireLatestValid(RuleCraftPrincipal actor,UUID serviceId,DecisionVersion candidate){if(candidate.getValidationStatus()!=VersionValidationStatus.VALID)conflict("RC-WORKFLOW-VERSION-INVALID","Only a valid captured version can enter approval or promotion.");var latest=latest(actor,serviceId);if(latest==null||!latest.getId().equals(candidate.getId()))conflict("RC-WORKFLOW-VERSION-STALE","A newer captured version exists. Open or review a request for the latest version.");}
    private DecisionVersion latest(RuleCraftPrincipal actor,UUID serviceId){return versions.findFirstByDecisionServiceIdAndTenantIdOrderByVersionNumberDesc(serviceId,actor.tenantId()).orElse(null);}private DecisionVersion version(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID versionId){if(versionId==null)bad("RC-WORKFLOW-VERSION","Choose a captured decision version.");return versions.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(versionId,serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);}private DecisionChangeRequest require(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID requestId){return requests.findByIdAndTenantIdAndProjectIdAndServiceId(requestId,actor.tenantId(),projectId,serviceId).orElseThrow(this::notFound);}private void context(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){access.requireVisible(actor,projectId);service(actor,projectId,serviceId);}private void service(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){if(services.findByIdAndTenantIdAndProjectId(serviceId,actor.tenantId(),projectId).isEmpty())throw notFound();}
    private RequestView view(RuleCraftPrincipal actor,DecisionChangeRequest value,DecisionVersion latest){var candidate=versions.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(value.getDecisionVersionId(),value.getServiceId(),actor.tenantId(),value.getProjectId()).orElseThrow(this::notFound);return new RequestView(value.getId(),value.getRequestNumber(),candidate.getId(),candidate.getVersionNumber(),candidate.getLabel(),candidate.getValidationStatus(),value.getTitle(),value.getSummary(),value.getState(),value.getCreatedByName(),value.getCreatedAt(),value.getUpdatedAt(),value.getVersion(),latest!=null&&!latest.getId().equals(candidate.getId()));}private EventView event(DecisionChangeEvent value){return new EventView(value.getId(),value.getEventType(),value.getFromState(),value.getToState(),value.getNote(),value.getActorName(),value.getCreatedAt());}private PromotionView promotion(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,DecisionPromotion value){var candidate=versions.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(value.getDecisionVersionId(),serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);return new PromotionView(value.getRequestId(),candidate.getId(),candidate.getVersionNumber(),candidate.getLabel(),value.getPromotedByName(),value.getPromotedAt(),value.getRevision());}
    private void record(RuleCraftPrincipal actor,DecisionChangeRequest request,String action){audit.record(actor.tenantId(),actor.userId(),"CHANGE_REQUEST_"+action,"DECISION_CHANGE_REQUEST",request.getId(),Map.of("serviceId",request.getServiceId(),"decisionVersionId",request.getDecisionVersionId(),"state",request.getState().name()));}private String clean(String value,int max,String code,String message){var result=value==null?"":value.strip();if(result.isBlank()||result.length()>max)bad(code,message);return result;}private String optional(String value,int max,String code,String message){if(value==null||value.isBlank())return null;var result=value.strip();if(result.length()>max)bad(code,message);return result;}private DomainProblemException notFound(){return new DomainProblemException(HttpStatus.NOT_FOUND,"RC-WORKFLOW-NOT-FOUND","Approval workflow resource not found.");}private void bad(String code,String message){throw new DomainProblemException(HttpStatus.BAD_REQUEST,code,message);}private void conflict(String code,String message){throw new DomainProblemException(HttpStatus.CONFLICT,code,message);}
    public record CreateCommand(UUID clientRequestId,UUID decisionVersionId,String title,String summary){}public record TransitionCommand(UUID clientRequestId,Long expectedVersion,String note){}public record RequestView(UUID id,int requestNumber,UUID decisionVersionId,int decisionVersionNumber,String decisionVersionLabel,VersionValidationStatus validationStatus,String title,String summary,ChangeRequestState state,String createdByName,Instant createdAt,Instant updatedAt,long version,boolean stale){}public record EventView(UUID id,String eventType,ChangeRequestState fromState,ChangeRequestState toState,String note,String actorName,Instant createdAt){}public record PromotionView(UUID changeRequestId,UUID decisionVersionId,int decisionVersionNumber,String decisionVersionLabel,String promotedByName,Instant promotedAt,long revision){}public record WorkflowView(List<RequestView> requests,PromotionView promotion,String accessRole){}public record RequestDetail(RequestView request,List<EventView> events){}
}
